export const poi_tiles  =  {
    poi_standard  :  {
        poi_name  :  '标准视图',
        poi_url  :  'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png'
    },
    poi_dark  :  {
        poi_name  :  '暗黑模式',
        poi_url  :  'https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}.png'
    },
    poi_terrain  :  {
        poi_name  :  '地形图',
        poi_url  :  'https://{s}.tile.opentopomap.org/{z}/{x}/{y}.png'
    }
}

export const poi_facilities  =  {
    poi_gas  :  { poi_icon  :  '⛽', poi_color  :  '#FFD700', poi_label  :  '加油站' },
    poi_restaurant  :  { poi_icon  :  '🍽️', poi_color  :  '#FF6B6B', poi_label  :  '餐厅' },
    poi_hotel  :  { poi_icon  :  '🏨', poi_color  :  '#4A90E2', poi_label  :  '酒店' }
}

export function Poi_generate(poi_coords, poi_count = 3) {
    const poi_points  =  []
    for (let i = 0; i < poi_count; i++) {
        const poi_offset_lat  =  (Math.random() - 0.5) * 0.02
        const poi_offset_lng  =  (Math.random() - 0.5) * 0.02
        poi_points.push([
            poi_coords[0] + poi_offset_lat,
            poi_coords[1] + poi_offset_lng
        ])
    }
    return poi_points
}

export function Poi_distribute(poi_routepoints) {
    const poi_all_points  =  []
    for (let i = 0; i < poi_routepoints.length - 1; i++) {
        const poi_start  =  poi_routepoints[i]
        const poi_end  =  poi_routepoints[i + 1]
        const poi_mid  =  [(poi_start[0] + poi_end[0]) / 2, (poi_start[1] + poi_end[1]) / 2]
        const poi_segment_points  =  Poi_generate(poi_mid, 2)
        poi_all_points.push(...poi_segment_points)
    }
    return poi_all_points
}

